<script lang="ts">
 import {onMount} from 'svelte';import type {WorkbenchSnapshot,WorkbenchState} from '../lib/workbench-state.js';import {contextActions,type ContextAction} from '../lib/context-actions.js';export let state:WorkbenchState;let menu:{x:number;y:number;actions:ContextAction[];snapshot:WorkbenchSnapshot}|undefined;
 const close=()=>menu=undefined;function run(action:ContextAction){if(menu)action.run(menu.snapshot);close()}
 onMount(()=>{const context=(event:MouseEvent)=>{const target=event.target as HTMLElement;if(target.closest('input,textarea,select,iframe,.xterm,.cm-editor,.atlas-context-menu,.dv-tab,.file-list,[contenteditable="true"]'))return;const contextTarget=target.closest<HTMLElement>('[data-context-id]'),base=state.snapshot(),contextId=contextTarget?.dataset.contextId??base.contextId,snapshot={...base,contextId,selection:contextTarget?{id:contextId,type:contextTarget.dataset.contextKind??'context'}:base.selection},actions=contextActions.filter(action=>action.available(snapshot));if(!actions.length)return;event.preventDefault();menu={x:event.clientX,y:event.clientY,actions,snapshot}},key=(event:KeyboardEvent)=>event.key==='Escape'&&close(),click=(event:MouseEvent)=>{if(!(event.target as HTMLElement).closest('.global-context-menu'))close()};document.addEventListener('contextmenu',context);document.addEventListener('keydown',key);document.addEventListener('pointerdown',click);return()=>{document.removeEventListener('contextmenu',context);document.removeEventListener('keydown',key);document.removeEventListener('pointerdown',click)}});
</script>
{#if menu}<div class="global-context-menu" role="menu" style={`left:${Math.min(menu.x,innerWidth-230)}px;top:${Math.min(menu.y,innerHeight-300)}px`}>{#each ['workflow','observe','navigate','intelligence'] as group}{#each menu.actions.filter(action=>action.group===group) as action}<button role="menuitem" onclick={()=>run(action)}><span>{action.label}</span><small>{action.placement}</small></button>{/each}{/each}</div>{/if}
<style>.global-context-menu{position:fixed;z-index:1500;width:220px;padding:4px;border:1px solid #354252;border-radius:5px;background:#111821;box-shadow:0 16px 45px #000b}.global-context-menu button{display:flex;width:100%;justify-content:space-between;gap:8px;padding:7px 8px;border:0;background:transparent;text-align:left}.global-context-menu button:hover,.global-context-menu button:focus-visible{background:#1b2733;color:var(--accent);outline:none}.global-context-menu small{color:#708090}</style>
